"use client"

import * as React from "react"
import {
  ArrowHorizontalIcon,
  ParagraphSpacingIcon,
  TextSmallcapsIcon,
} from "@hugeicons/core-free-icons"
import { type IconSvgElement } from "@hugeicons/react"

import { useIsMobile } from "@/hooks/use-mobile"
import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
} from "@/styles/base-nova/ui/card"
import { FieldGroup, FieldSeparator } from "@/styles/base-nova/ui/field"
import { FontPicker } from "@/app/(app)/(typeset)/components/font-picker"
import { TypesetGetCodeDrawer } from "@/app/(app)/(typeset)/components/get-code-drawer"
import { TypesetMainMenu } from "@/app/(app)/(typeset)/components/main-menu"
import { OptionPicker } from "@/app/(app)/(typeset)/components/option-picker"
import { TypesetRandomButton } from "@/app/(app)/(typeset)/components/random-button"
import {
  TYPESET_FLOWS,
  TYPESET_LEADINGS,
  TYPESET_MEASURES,
  TYPESET_SIZES,
  useTypesetSearchParams,
} from "@/app/(app)/(typeset)/lib/search-params"

const LineHeightIcon: IconSvgElement = [
  [
    "path",
    {
      d: "M4.5 3.5H19.5",
      stroke: "currentColor",
      strokeLinecap: "round",
      strokeWidth: "1.5",
      key: "0",
    },
  ],
  [
    "path",
    {
      d: "M4.5 20.5H19.5",
      stroke: "currentColor",
      strokeLinecap: "round",
      strokeWidth: "1.5",
      key: "1",
    },
  ],
  [
    "path",
    {
      d: "M17 17L14.8905 11.4741C13.9109 8.90801 13.4211 7.625 12.625 7.625C11.8289 7.625 11.3391 8.90801 10.3595 11.4741L8.25 17",
      stroke: "currentColor",
      strokeLinecap: "round",
      strokeWidth: "1.5",
      key: "2",
    },
  ],
  [
    "path",
    {
      d: "M9.5 13H15.75",
      stroke: "currentColor",
      strokeLinecap: "round",
      strokeWidth: "1.5",
      key: "3",
    },
  ],
]

export function TypesetCustomizer() {
  const [params, setParams] = useTypesetSearchParams()
  const isMobile = useIsMobile()
  const anchorRef = React.useRef<HTMLDivElement | null>(null)

  // Resolve the rhythm to px off the current size: leading is a multiple,
  // flow is an em value.
  const sizePx = Number(params.scale)
  const leadingPx = Math.round(sizePx * Number(params.leading))
  const flowPx = Math.round(sizePx * parseFloat(params.flow))

  return (
    <Card
      className="dark isolate z-10 max-h-full min-h-0 w-full self-start rounded-2xl bg-card/90 backdrop-blur-xl md:w-(--customizer-width)"
      ref={anchorRef}
      size="sm"
    >
      <CardHeader className="hidden items-center justify-between gap-2 border-b md:flex">
        <TypesetMainMenu />
      </CardHeader>
      <CardContent className="no-scrollbar min-h-0 flex-1 overflow-x-auto overflow-y-hidden max-md:px-0 md:overflow-y-auto">
        <FieldGroup className="flex-row gap-2.5 py-px **:data-[slot=field-separator]:-mx-4 **:data-[slot=field-separator]:w-auto max-md:px-3 md:flex-col md:gap-3.25">
          {/* Below ~60ch the viewport already constrains width, so measure
              does nothing: hide it. */}
          <OptionPicker
            label="Measure"
            className="max-[28rem]:hidden"
            isMobile={isMobile}
            anchorRef={anchorRef}
            param="measure"
            icon={ArrowHorizontalIcon}
            options={TYPESET_MEASURES}
            value={params.measure}
            onChange={(measure) => setParams({ measure })}
          />
          <FieldSeparator className="hidden md:block" />
          <FontPicker
            label="Heading"
            param="heading"
            isMobile={isMobile}
            anchorRef={anchorRef}
          />
          <FontPicker
            label="Body"
            param="body"
            isMobile={isMobile}
            anchorRef={anchorRef}
          />
          <FontPicker
            label="Mono"
            param="mono"
            isMobile={isMobile}
            anchorRef={anchorRef}
          />
          <FieldSeparator className="hidden md:block" />
          <OptionPicker
            label="Size"
            isMobile={isMobile}
            anchorRef={anchorRef}
            param="scale"
            icon={TextSmallcapsIcon}
            options={TYPESET_SIZES}
            value={params.scale}
            onChange={(scale) => setParams({ scale })}
          />
          <OptionPicker
            label="Leading"
            isMobile={isMobile}
            anchorRef={anchorRef}
            param="leading"
            icon={LineHeightIcon}
            options={TYPESET_LEADINGS}
            value={params.leading}
            onChange={(leading) => setParams({ leading })}
          />
          <OptionPicker
            label="Flow"
            isMobile={isMobile}
            anchorRef={anchorRef}
            param="flow"
            icon={ParagraphSpacingIcon}
            options={TYPESET_FLOWS}
            value={params.flow}
            onChange={(flow) => setParams({ flow })}
          />
          {process.env.NODE_ENV === "development" && (
            <div className="hidden px-1 pt-0.5 text-center font-mono text-xs text-muted-foreground tabular-nums md:block">
              {sizePx}px / {leadingPx}px / {flowPx}px
            </div>
          )}
          {/* Scroll-end spacer: the group is a CQ container (inline-size
              containment), so trailing padding cannot grow it. */}
          <div aria-hidden className="w-0.5 shrink-0 md:hidden" />
        </FieldGroup>
      </CardContent>
      <CardFooter className="flex min-w-0 flex-row-reverse gap-2 border-t md:flex-col md:**:[button]:w-full">
        <TypesetRandomButton className="min-w-0 flex-1 md:flex-none" />
        <TypesetGetCodeDrawer className="min-w-0 flex-1 touch-manipulation bg-transparent! px-2! py-0! text-sm! transition-none select-none hover:bg-muted! md:flex-none xl:hidden pointer-coarse:h-10!" />
      </CardFooter>
    </Card>
  )
}
"use client"

import {
  SquareLock01Icon,
  SquareUnlock01Icon,
} from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"
import { cn } from "cn"

import {
  useLocks,
  type LockableParam,
} from "@/app/(app)/(typeset)/hooks/use-locks"

export function LockButton({
  param,
  className,
}: {
  param: LockableParam
  className?: string
}) {
  const { isLocked, toggleLock } = useLocks()
  const locked = isLocked(param)

  return (
    <button
      type="button"
      title={locked ? "Unlock" : "Lock"}
      aria-label={locked ? "Unlock" : "Lock"}
      onClick={() => toggleLock(param)}
      data-locked={locked}
      className={cn(
        "flex size-4 cursor-pointer items-center justify-center rounded opacity-0 ring-foreground/60 transition-opacity outline-none group-focus-within/picker:opacity-100 group-hover/picker:opacity-100 focus:opacity-100 focus-visible:ring-1 data-[locked=true]:opacity-100 max-md:hidden pointer-coarse:hidden",
        className
      )}
    >
      <HugeiconsIcon
        icon={locked ? SquareLock01Icon : SquareUnlock01Icon}
        strokeWidth={2}
        className="size-5 text-foreground"
      />
    </button>
  )
}
"use client"

import * as React from "react"
import { Menu as MenuPrimitive } from "@base-ui/react/menu"
import { cn } from "cn"
import { CheckIcon } from "lucide-react"

// Copy of create's picker with lucide icons instead of IconPlaceholder (its
// useDesignSystemSearchParams read must not mount on /typeset).
function Picker({ ...props }: MenuPrimitive.Root.Props) {
  return <MenuPrimitive.Root data-slot="dropdown-menu" {...props} />
}

function PickerTrigger({ className, ...props }: MenuPrimitive.Trigger.Props) {
  return (
    <MenuPrimitive.Trigger
      data-slot="dropdown-menu-trigger"
      className={cn(
        "relative w-36 shrink-0 touch-manipulation rounded-xl p-3 ring-1 ring-foreground/10 select-none hover:bg-muted focus-visible:ring-foreground/50 focus-visible:outline-none disabled:opacity-50 data-popup-open:bg-muted md:w-full md:rounded-lg md:px-2.5 md:py-2",
        className
      )}
      {...props}
    />
  )
}

function PickerContent({
  align = "start",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 20,
  anchor,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "anchor"
  >) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
      >
        <MenuPrimitive.Popup
          data-slot="dropdown-menu-content"
          className={cn(
            "cn-menu-target z-50 no-scrollbar max-h-(--available-height) w-[calc(var(--available-width)-(--spacing(6)))] min-w-32 origin-(--transform-origin) translate-y-2 overflow-x-hidden overflow-y-auto rounded-xl border-0 bg-neutral-950/80 p-1.5 text-neutral-100 ring-1 ring-neutral-950/80 backdrop-blur-xl outline-none md:w-52 dark:bg-neutral-800/90 dark:ring-neutral-700/50 data-closed:overflow-hidden",
            className
          )}
          {...props}
        />
      </MenuPrimitive.Positioner>
      {/* Clicks inside the preview iframe never reach this document, so this
          shield catches outside-clicks over it. left-54 clears the card. */}
      <div className="absolute inset-y-0 right-0 left-54 z-40 bg-transparent" />
    </MenuPrimitive.Portal>
  )
}

function PickerGroup({ ...props }: MenuPrimitive.Group.Props) {
  return <MenuPrimitive.Group data-slot="dropdown-menu-group" {...props} />
}

function PickerLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.GroupLabel
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(
        "px-2 py-1.5 text-xs font-medium text-neutral-400 data-inset:pl-8",
        className
      )}
      {...props}
    />
  )
}

function PickerItem({
  className,
  inset,
  variant = "default",
  ...props
}: MenuPrimitive.Item.Props & {
  inset?: boolean
  variant?: "default" | "destructive"
}) {
  return (
    <MenuPrimitive.Item
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(
        "group/dropdown-menu-item relative flex cursor-default items-center gap-2 rounded-lg px-2 py-1.5 text-sm font-medium outline-hidden select-none **:text-neutral-100 focus:bg-neutral-600 focus:text-neutral-100 focus:**:text-neutral-100 data-inset:pl-8 dark:focus:bg-neutral-700/80 pointer-coarse:gap-3 pointer-coarse:py-2.5 pointer-coarse:pl-3 pointer-coarse:text-base data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    />
  )
}

// Lets pickers preview an item's value on hover/highlight by declaring a
// single onItemPreview on the group instead of wiring every radio item.
const PickerPreviewContext = React.createContext<
  ((value: string) => void) | null
>(null)

function PickerRadioGroup({
  onItemPreview,
  ...props
}: MenuPrimitive.RadioGroup.Props & {
  onItemPreview?: (value: string) => void
}) {
  return (
    <PickerPreviewContext.Provider value={onItemPreview ?? null}>
      <MenuPrimitive.RadioGroup
        data-slot="dropdown-menu-radio-group"
        {...props}
      />
    </PickerPreviewContext.Provider>
  )
}

function PickerRadioItem({
  className,
  children,
  value,
  onMouseMove,
  onFocus,
  ...props
}: MenuPrimitive.RadioItem.Props) {
  const onItemPreview = React.useContext(PickerPreviewContext)

  return (
    <MenuPrimitive.RadioItem
      data-slot="dropdown-menu-radio-item"
      value={value}
      // Previews apply when the pointer settles: every mousemove re-arms the
      // provider's trailing timer, so nothing applies while the cursor is in
      // motion. Base UI moves DOM focus to the highlighted item, so onFocus
      // covers keyboard (arrow key) browsing.
      onMouseMove={(event) => {
        onMouseMove?.(event)
        onItemPreview?.(value as string)
      }}
      onFocus={(event) => {
        onFocus?.(event)
        onItemPreview?.(value as string)
      }}
      className={cn(
        "relative flex cursor-default items-center gap-2 rounded-lg py-1.5 pr-8 pl-2 text-sm font-medium outline-hidden select-none **:text-neutral-100 focus:bg-neutral-600 focus:text-neutral-100 focus:**:text-neutral-100 data-inset:pl-8 dark:focus:bg-neutral-700/80 pointer-coarse:gap-3 pointer-coarse:py-2.5 pointer-coarse:pl-3 pointer-coarse:text-base data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className
      )}
      {...props}
    >
      <span
        className="pointer-events-none absolute right-2 flex items-center justify-center"
        data-slot="dropdown-menu-radio-item-indicator"
      >
        <MenuPrimitive.RadioItemIndicator>
          <CheckIcon className="size-4 pointer-coarse:size-5" />
        </MenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </MenuPrimitive.RadioItem>
  )
}

function PickerSeparator({
  className,
  ...props
}: MenuPrimitive.Separator.Props) {
  return (
    <MenuPrimitive.Separator
      data-slot="dropdown-menu-separator"
      className={cn(
        "-mx-1.5 my-1.5 h-px bg-neutral-600 dark:bg-neutral-700",
        className
      )}
      {...props}
    />
  )
}

function PickerShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="dropdown-menu-shortcut"
      className={cn(
        "ml-auto text-xs tracking-widest text-neutral-400! group-focus/dropdown-menu-item:text-neutral-100",
        className
      )}
      {...props}
    />
  )
}

export {
  Picker,
  PickerTrigger,
  PickerContent,
  PickerGroup,
  PickerItem,
  PickerLabel,
  PickerRadioGroup,
  PickerRadioItem,
  PickerSeparator,
  PickerShortcut,
}
"use client"

import { LockButton } from "@/app/(app)/(typeset)/components/lock-button"
import {
  Picker,
  PickerContent,
  PickerGroup,
  PickerLabel,
  PickerRadioGroup,
  PickerRadioItem,
  PickerSeparator,
  PickerTrigger,
} from "@/app/(app)/(typeset)/components/picker"
import { usePreviewOverride } from "@/app/(app)/(typeset)/components/preview-override"
import { findFont, FONTS } from "@/app/(app)/(typeset)/lib/fonts"
import {
  coerceTypesetValue,
  useTypesetSearchParams,
} from "@/app/(app)/(typeset)/lib/search-params"

export function FontPicker({
  label,
  param,
  isMobile,
  anchorRef,
}: {
  label: string
  param: "body" | "heading" | "mono"
  isMobile: boolean
  anchorRef: React.RefObject<HTMLDivElement | null>
}) {
  const [params, setParams] = useTypesetSearchParams()
  const { setOverride, clearOverride } = usePreviewOverride()
  const currentValue =
    param === "body"
      ? params.body
      : param === "heading"
        ? params.heading
        : params.mono
  const bodyFont = findFont(params.body) ?? FONTS[0]
  const inheritsBodyFont = param === "heading" && currentValue === "inherit"
  const currentFont = inheritsBodyFont
    ? bodyFont
    : (findFont(currentValue) ?? bodyFont)

  // Every picker offers every font (no type filter); grouping is just labels.
  const groupedFonts = [
    { label: "Sans", fonts: FONTS.filter((f) => f.type === "sans") },
    { label: "Serif", fonts: FONTS.filter((f) => f.type === "serif") },
    { label: "Mono", fonts: FONTS.filter((f) => f.type === "mono") },
  ]

  return (
    <div className="group/picker relative">
      <Picker
        onOpenChange={(open) => {
          if (!open) {
            clearOverride()
          }
        }}
      >
        <PickerTrigger>
          <div className="flex flex-col justify-start text-left">
            <div className="text-xs text-muted-foreground">{label}</div>
            <div className="line-clamp-1 max-w-[80%] truncate text-sm font-medium text-foreground">
              {currentFont.label}
            </div>
          </div>
          <div
            className="pointer-events-none absolute top-1/2 right-4 flex size-4 -translate-y-1/2 items-center justify-center text-base text-foreground select-none md:right-2.5"
            style={{ fontFamily: currentFont.value }}
          >
            Aa
          </div>
        </PickerTrigger>
        <PickerContent
          anchor={isMobile ? anchorRef : undefined}
          side={isMobile ? "top" : "right"}
          align={isMobile ? "center" : "start"}
          className="max-h-96"
          onMouseLeave={clearOverride}
        >
          <PickerRadioGroup
            value={currentValue}
            onValueChange={(next) => {
              if (param === "body") {
                const value = coerceTypesetValue("body", next)
                if (value !== null) setParams({ body: value })
              } else if (param === "heading") {
                const value = coerceTypesetValue("heading", next)
                if (value !== null) setParams({ heading: value })
              } else {
                const value = coerceTypesetValue("mono", next)
                if (value !== null) setParams({ mono: value })
              }
            }}
            onItemPreview={
              isMobile
                ? undefined
                : (next) => {
                    const value = coerceTypesetValue(param, next)
                    if (value !== null) {
                      setOverride({ [param]: value })
                    }
                  }
            }
          >
            {param === "heading" ? (
              <>
                <PickerGroup>
                  <PickerRadioItem value="inherit">
                    {bodyFont.label}
                  </PickerRadioItem>
                </PickerGroup>
                <PickerSeparator />
              </>
            ) : null}
            {groupedFonts.map((group) => (
              <PickerGroup key={group.label}>
                <PickerLabel>{group.label}</PickerLabel>
                {group.fonts.map((font) => (
                  <PickerRadioItem key={font.id} value={font.id}>
                    {font.label}
                  </PickerRadioItem>
                ))}
              </PickerGroup>
            ))}
          </PickerRadioGroup>
        </PickerContent>
      </Picker>
      <LockButton
        param={param}
        className="absolute top-1/2 right-8 -translate-y-1/2"
      />
    </div>
  )
}
